    # Solid separator rows and columns divide the grid into equal-sized panels.
    separators = {v for v in set(x for row in grid for x in row) if any(all(x == v for x in row) for row in grid) and any(all(grid[r][c] == v for r in range(h)) for c in range(w))}
    sep = next(iter(separators)) if separators else max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    row_bands = []
    start = 0
    for r in range(h):
        if all(v == sep for v in grid[r]):
            if start < r:
                row_bands.append((start, r))
            start = r + 1
    if start < h:
        row_bands.append((start, h))
    col_bands = []
    start = 0
    for c in range(w):
        if all(grid[r][c] == sep for r in range(h)):
            if start < c:
                col_bands.append((start, c))
            start = c + 1
    if start < w:
        col_bands.append((start, w))

    # The non-solid panel contains the pattern to copy; the first panel of
    # each row supplies that row's output color.
    template = None
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            cells = [(r-r0, c-c0) for r in range(r0,r1) for c in range(c0,c1)
                     if grid[r][c] not in (0, sep)]
            if not cells:
                continue
